-- Written by Visual Paradigm's Generate Database wizard (Tools > DB > Generate Database, SQLite,
-- Generate DDL) from the ERD c42_erd; copied by tools/vp_generate_db.py.
CREATE TABLE customer (customer_id varchar(20) NOT NULL, first_name varchar(50) NOT NULL, middle_name varchar(50), last_name varchar(50) NOT NULL, email varchar(120) NOT NULL UNIQUE, phone varchar(20), date_of_birth date, PRIMARY KEY (customer_id));
CREATE TABLE customer_vip (vip_level integer(10) NOT NULL, discount_rate numeric(4, 3) NOT NULL, reward_points integer(10) NOT NULL, customer_id varchar(20) NOT NULL, PRIMARY KEY (customer_id), FOREIGN KEY(customer_id) REFERENCES customer(customer_id));
CREATE TABLE customer_new (registered_date date NOT NULL, welcome_voucher varchar(30), customer_id varchar(20) NOT NULL, PRIMARY KEY (customer_id), FOREIGN KEY(customer_id) REFERENCES customer(customer_id));
CREATE TABLE address (address_id varchar(20) NOT NULL, house_number varchar(20) NOT NULL, street varchar(100) NOT NULL, district varchar(60) NOT NULL, city varchar(60) NOT NULL, customer_id varchar(20) NOT NULL, PRIMARY KEY (address_id), FOREIGN KEY(customer_id) REFERENCES customer(customer_id));
CREATE TABLE category (category_id varchar(20) NOT NULL, name varchar(60) NOT NULL UNIQUE, detail_kind varchar(12) NOT NULL, description varchar(300), PRIMARY KEY (category_id));
CREATE TABLE product (product_id varchar(20) NOT NULL, name varchar(200) NOT NULL, price numeric(12, 2) NOT NULL, stock_quantity integer(10) NOT NULL, image_url varchar(255), description varchar(500), category_id varchar(20) NOT NULL, PRIMARY KEY (product_id), FOREIGN KEY(category_id) REFERENCES category(category_id));
CREATE TABLE artist (artist_id varchar(20) NOT NULL, name varchar(120) NOT NULL, nationality varchar(60), life_years varchar(20), PRIMARY KEY (artist_id));
CREATE TABLE painting (style varchar(40) NOT NULL, subject varchar(40) NOT NULL, dominant_color varchar(20) NOT NULL, medium varchar(60) NOT NULL, year_created integer(10) NOT NULL, width_cm integer(10) NOT NULL, height_cm integer(10) NOT NULL, product_id varchar(20) NOT NULL, artist_id varchar(20) NOT NULL, PRIMARY KEY (product_id), FOREIGN KEY(product_id) REFERENCES product(product_id), FOREIGN KEY(artist_id) REFERENCES artist(artist_id));
CREATE TABLE frame (material varchar(40) NOT NULL, color varchar(20) NOT NULL, size_label varchar(20) NOT NULL, product_id varchar(20) NOT NULL, PRIMARY KEY (product_id), FOREIGN KEY(product_id) REFERENCES product(product_id));
CREATE TABLE product_feature (model_version varchar(40) NOT NULL, feature_vector blob NOT NULL, updated_at timestamp NOT NULL, product_id varchar(20) NOT NULL, PRIMARY KEY (product_id), FOREIGN KEY(product_id) REFERENCES product(product_id));
CREATE TABLE cart (cart_id varchar(20) NOT NULL, created_date timestamp NOT NULL, updated_date timestamp NOT NULL, customer_id varchar(20) NOT NULL UNIQUE, PRIMARY KEY (cart_id), FOREIGN KEY(customer_id) REFERENCES customer(customer_id));
CREATE TABLE cart_item (quantity integer(10) NOT NULL, cart_price numeric(12, 2) NOT NULL, cart_id varchar(20) NOT NULL, product_id varchar(20) NOT NULL, PRIMARY KEY (cart_id, product_id), FOREIGN KEY(cart_id) REFERENCES cart(cart_id), FOREIGN KEY(product_id) REFERENCES product(product_id));
CREATE TABLE orders (order_id varchar(20) NOT NULL, order_date timestamp NOT NULL, status varchar(12) NOT NULL, total_amount numeric(12, 2) NOT NULL, customer_id varchar(20) NOT NULL, PRIMARY KEY (order_id), FOREIGN KEY(customer_id) REFERENCES customer(customer_id));
CREATE TABLE order_item (quantity integer(10) NOT NULL, unit_price numeric(12, 2) NOT NULL, order_id varchar(20) NOT NULL, product_id varchar(20) NOT NULL, PRIMARY KEY (order_id, product_id), FOREIGN KEY(order_id) REFERENCES orders(order_id), FOREIGN KEY(product_id) REFERENCES product(product_id));
CREATE TABLE shipping (shipping_id varchar(20) NOT NULL, carrier varchar(60), tracking_number varchar(40), shipping_fee numeric(12, 2) NOT NULL, status varchar(12) NOT NULL, delivered_date date, order_id varchar(20) NOT NULL UNIQUE, address_id varchar(20) NOT NULL, PRIMARY KEY (shipping_id), FOREIGN KEY(order_id) REFERENCES orders(order_id), FOREIGN KEY(address_id) REFERENCES address(address_id));
CREATE TABLE payment (payment_id varchar(20) NOT NULL, method varchar(6) NOT NULL, amount numeric(12, 2) NOT NULL, payment_date timestamp, status varchar(10) NOT NULL, order_id varchar(20) NOT NULL, PRIMARY KEY (payment_id), FOREIGN KEY(order_id) REFERENCES orders(order_id));
CREATE TABLE pay_cash (cash_received numeric(12, 2), change_amount numeric(12, 2), payment_id varchar(20) NOT NULL, PRIMARY KEY (payment_id), FOREIGN KEY(payment_id) REFERENCES payment(payment_id));
CREATE TABLE pay_credit (card_holder varchar(100) NOT NULL, bank_name varchar(60) NOT NULL, card_last4 varchar(4) NOT NULL, authorization_code varchar(40), payment_id varchar(20) NOT NULL, PRIMARY KEY (payment_id), FOREIGN KEY(payment_id) REFERENCES payment(payment_id));
